			t.Fatalf("%s: code = %s", target, code)
		}
	}
}

func TestNotificationDeliveryHistoryStorageUnavailable(t *testing.T) {
	st, err := openStoreForUnavailable(t)
	if err != nil {
		t.Fatalf("open: %v", err)
	}
